package com.attentiontwin.app;
import android.content.*;import android.database.Cursor;import android.view.*;import android.widget.*;import androidx.core.graphics.Insets;import androidx.core.view.WindowInsetsCompat;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import javax.crypto.spec.SecretKeySpec;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class InboxAndKeyboardTest {
 @Before public void key(){InboxCrypto.keys=()->new SecretKeySpec(new byte[16],"AES");}
 @After public void reset(){InboxCrypto.keys=InboxCrypto::androidKey;}
 @Test public void messageContentEncryptedAndDuplicatesCountOnce() throws Exception{Context c=RuntimeEnvironment.getApplication();try(InboxStore store=new InboxStore(c)){long now=System.currentTimeMillis();assertTrue(store.capture("one","group","app","App",now,"real","Sender","Private fire message","IMPORTANT","Local")>0);assertEquals(-1,store.capture("one","group","app","App",now,"real","Sender","Private fire message","IMPORTANT","Local"));assertEquals(1,store.messages(false).length());assertEquals("Private fire message",store.messages(false).getJSONObject(0).getString("text"));try(Cursor cursor=store.getReadableDatabase().rawQuery("SELECT payload FROM messages",null)){assertTrue(cursor.moveToFirst());assertFalse(cursor.getString(0).contains("Private"));assertTrue(cursor.getString(0).startsWith("v1:"));}}}
 @Test public void testsAreSeparateAndClearingRemovesContent() throws Exception{try(InboxStore store=new InboxStore(RuntimeEnvironment.getApplication())){store.capture("test","g","app","App",System.currentTimeMillis(),"test","Sample","hello","CASUAL","Local");assertEquals(0,store.messages(false).length());assertEquals(1,store.messages(true).length());store.clear();assertEquals(0,store.messages(true).length());}}
 @Test public void modernKeyboardInsetAppliedExactlyOnce(){FrameLayout content=new FrameLayout(RuntimeEnvironment.getApplication());View web=new View(content.getContext());content.addView(web,new FrameLayout.LayoutParams(-1,-1));WindowInsetsCompat insets=new WindowInsetsCompat.Builder().setInsets(WindowInsetsCompat.Type.systemBars(),Insets.of(0,24,0,30)).setInsets(WindowInsetsCompat.Type.ime(),Insets.of(0,0,0,300)).build();KeyboardInsets.apply(content,insets,true);content.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(900,View.MeasureSpec.EXACTLY));assertEquals(300,content.getPaddingBottom());assertEquals(576,web.getMeasuredHeight());KeyboardInsets.apply(content,insets,true);assertEquals(300,content.getPaddingBottom());}
}
